from __future__ import annotations

from pathlib import Path

from vitools_sync.emitters.base import copy_skills, load_mcp_servers


def emit_mistral(root: Path, target: Path) -> list[Path]:
    written: list[Path] = []
    written.extend(copy_skills(root, target / "skills"))
    servers = load_mcp_servers(root)
    lines = [
        "# Generated by vitools-sync — Mistral Vibe config fragment",
        "# Merge [[mcp_servers]] tables into .vibe/config.toml",
        "",
    ]
    for name, spec in servers.items():
        lines.append("[[mcp_servers]]")
        lines.append(f'name = "{name}"')
        if spec.get("transport") == "remote":
            lines.append('transport = "http"')
            lines.append(f'url = "{spec.get("url", "")}"')
        else:
            lines.append('transport = "stdio"')
            command = spec.get("command", "npx")
            args = spec.get("args") or []
            cmd = " ".join([command, *args])
            lines.append(f'command = "{cmd}"')
        lines.append("")
    config_path = target / "config.toml.fragment"
    config_path.parent.mkdir(parents=True, exist_ok=True)
    config_path.write_text("\n".join(lines), encoding="utf-8")
    written.append(config_path)
    return written
